import sys
sys.setrecursionlimit(10000)

tok = sys.stdin.read().split()
pos = [0]

def parse():
    pos[0] += 1
    d = []
    while tok[pos[0]] != '}':
        k = tok[pos[0]]
        pos[0] += 1
        if tok[pos[0]] == '{':
            d.append((k, parse()))
        else:
            d.append((k, int(tok[pos[0]])))
            pos[0] += 1
    pos[0] += 1
    return d

def walk(d, prefix, out):
    for k, v in d:
        if isinstance(v, list):
            walk(v, prefix + k + '.', out)
        else:
            out.append(prefix + k + ' ' + str(v))

res = []
walk(parse(), '', res)
print('\n'.join(res))

